<template>
  <div class="page">
    <div class="feedback__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>留言反馈</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="nickname" label="反馈人" min-width="130" />
            <el-table-column prop="type" label="留言类型" min-width="150">
              <template #default="scope">
                {{ typeName(scope.row.type) }}
              </template>
            </el-table-column>
            <el-table-column prop="content" label="反馈内容" min-width="300" />
            <el-table-column prop="status" label="状态" min-width="110">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.status)" disable-transitions>{{ statusName(scope.row.status) }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createTime" label="反馈时间" min-width="200" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  v-if="scope.row.status === 0"
                  size="small"
                  type="primary"
                  @click="handleProcess(scope.row)"
                >
                  处理
                </el-button>
                <el-button v-else size="small" @click="handleView(scope.row)">查看</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>

      <el-dialog v-model="viewDialogVisible" title="留言详情" width="520px">
        <el-descriptions :column="1" border>
          <el-descriptions-item label="反馈人">{{ viewForm.nickname }}</el-descriptions-item>
          <el-descriptions-item label="留言类型">{{ typeName(viewForm.type) }}</el-descriptions-item>
          <el-descriptions-item label="反馈时间">{{ viewForm.createTime }}</el-descriptions-item>
          <el-descriptions-item label="留言内容">{{ viewForm.content }}</el-descriptions-item>
          <el-descriptions-item label="回复内容">
            <template v-if="viewForm.replies && viewForm.replies.length">
              <div v-for="item in viewForm.replies" :key="item.id" class="reply-item">
                <p class="reply-content">{{ item.content }}</p>
                <p class="reply-meta">{{ item.replierName }} · {{ item.createTime }}</p>
              </div>
            </template>
            <span v-else>暂无回复</span>
          </el-descriptions-item>
        </el-descriptions>
        <template #footer>
          <el-button type="primary" @click="viewDialogVisible = false">关 闭</el-button>
        </template>
      </el-dialog>
      <div class="feedback__pagination-wrap">
        <div class="totalnum">
          <h3>反馈统计</h3>
          <p>当前共 {{ tableData.length }} 条反馈</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, getCurrentInstance, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
const {proxy} = getCurrentInstance()
// 组件挂载时调用获取用户留言接口
onMounted(() => {
  getfeedbacklist()
})
// 获取用户留言接口
const getfeedbacklist = () => {
  proxy.$request.get('/api/usermessages').then((res) => {
    if (res.code === 1) {
      tableData.value = res.data
    } else {
      ElMessage.error('获取用户留言失败')
    }
  })
}


const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})
// 留言类型对应的中文名
const typeName = (type) => {
  const map = {
    feedback: '留言',
    suggestion: '建议',
    complaint: '投诉',
  }
  return map[type] || type
}
// 状态对应的中文名
const statusName = (status) => {
  const map = {
    0: '待处理',
    1: '已回复',
    2: '已关闭',
  }
  return map[status] || status
}
// 状态对应的 el-tag 颜色
const tagType = (status) => {
  const map = {
    0: 'danger',      // 待处理
    1: 'warning',     // 已回复
    2: 'success',     // 已关闭
  }
  return map[status] || 'info'
}

// 查看详情弹窗
const viewDialogVisible = ref(false)
const viewForm = ref({})
const handleView = (row) => {
  viewForm.value = row
  viewDialogVisible.value = true
}
// 处理：标记已关闭
const handleProcess = (row) => {
  ElMessageBox.confirm(`${row.nickname}：${row.content}`, '处理反馈', {
    confirmButtonText: '标记已关闭',
    cancelButtonText: '取消',
  })
    .then(() => {
      row.status = 2
      ElMessage.success('反馈已标记为已关闭')
    })
    .catch(() => {})
}

const tableData = ref([])
</script>

